import { join } from "node:path";
import fs from "node:fs";
import { fileURLToPath } from "node:url";
import fsPromises from "node:fs/promises";
import { Readable } from "node:stream";
/** Read a binary file */
export async function readFile(file) {
    const buf = await fsPromises.readFile(file);
    return new Uint8Array(buf.buffer, buf.byteOffset, buf.length / Uint8Array.BYTES_PER_ELEMENT);
}
/** Synchronously read a binary file */
export function readFileSync(file) {
    return fs.readFileSync(toPath(file));
}
/** Read a text file */
export async function readTextFile(file) {
    try {
        return await fsPromises.readFile(toPath(file), "utf-8");
    }
    catch (error) {
        throw new FsError(error);
    }
}
/** Synchronously read a text file */
export function readTextFileSync(file) {
    return fs.readFileSync(toPath(file), "utf-8");
}
/** Write a binary file */
export async function writeFile(file, content, createNew) {
    try {
        await fsPromises.writeFile(toPath(file), content, { flag: createNew ? "wx" : "w" });
    }
    catch (error) {
        throw new FsError(error);
    }
}
/** Synchronously write a binary file */
export function writeFileSync(file, content) {
    fs.writeFileSync(toPath(file), content);
}
/** Write a text file */
export async function writeTextFile(file, content, createNew) {
    try {
        await fsPromises.writeFile(toPath(file), content, { flag: createNew ? "wx" : "w" });
    }
    catch (error) {
        throw new FsError(error);
    }
}
/** Synchronously write a text file */
export function writeTextFileSync(file, content) {
    fs.writeFileSync(toPath(file), content);
}
/** Remove a file or folder */
export async function remove(file, recursive) {
    await fsPromises.rm(toPath(file), { recursive });
}
/** Synchronously remove a file or folder */
export function removeSync(file, recursive) {
    fs.rmSync(toPath(file), { recursive });
}
/** Synchronously returns a full normalized path */
export function realPathSync(file) {
    return fs.realpathSync(toPath(file));
}
/** Synchronously returns an iterable of a directory content */
export function* readDirSync(path) {
    try {
        const entries = fs.readdirSync(toPath(path), {
            withFileTypes: true,
        });
        for (const entry of entries) {
            yield {
                name: entry.name,
                isDirectory: entry.isDirectory(),
                isFile: entry.isFile(),
                isSymlink: entry.isSymbolicLink(),
            };
        }
    }
    catch (error) {
        throw new FsError(error);
    }
}
/** Synchronously creates a new directory with the specified path. */
export function mkdirSync(path, recursive) {
    try {
        return fs.mkdirSync(toPath(path), { recursive });
    }
    catch (error) {
        throw new FsError(error);
    }
}
export class FsError extends Error {
    constructor(cause) {
        super(cause.message);
        this.cause = cause;
    }
    get code() {
        if (this.cause.code === "ENOENT")
            return "not-found";
        if (this.cause.code === "EEXIST")
            return "exists";
        return "other";
    }
}
/** Synchronously returns a FileInfo for a specific path */
export function statSync(path) {
    try {
        const info = fs.statSync(toPath(path));
        return {
            get isFile() {
                return info.isFile();
            },
            get isDirectory() {
                return info.isDirectory();
            },
            get isSymlink() {
                return info.isSymbolicLink();
            },
            size: info.size,
            mtime: info.mtime,
            atime: info.atime,
            ctime: info.ctime,
            birthtime: info.birthtime,
        };
    }
    catch (error) {
        throw new FsError(error);
    }
}
export class FileWatcher {
    #controller = new AbortController();
    #path;
    constructor(path) {
        this.#path = path;
    }
    close() {
        this.#controller.abort();
    }
    async *[Symbol.asyncIterator]() {
        const { signal } = this.#controller;
        const iterator = fsPromises.watch(this.#path, { signal, recursive: true });
        for await (const change of iterator) {
            if (change.filename) {
                yield [join(this.#path, change.filename)];
            }
        }
    }
}
export function watchFiles(path) {
    return new FileWatcher(path);
}
export function readStream(file, start) {
    const nodeStream = fs.createReadStream(toPath(file), { start });
    return {
        readable: Readable.toWeb(nodeStream),
        [Symbol.dispose]: () => {
            nodeStream.destroy();
        },
    };
}
// Ensure file: URLs are converted to paths
function toPath(urlOrPath) {
    return urlOrPath.startsWith("file:") ? fileURLToPath(urlOrPath) : urlOrPath;
}
